function solveSudoku(board: string[][]): void {
  const ok = (r: number, c: number, d: string): boolean => {
    const br = r - (r % 3), bc = c - (c % 3);
    for (let k = 0; k < 9; k++) {
      if (board[r][k] === d || board[k][c] === d) return false;
      if (board[br + Math.floor(k / 3)][bc + (k % 3)] === d) return false;
    }
    return true;
  };
  const solve = (): boolean => {
    for (let r = 0; r < 9; r++)
      for (let c = 0; c < 9; c++) {
        if (board[r][c] !== ".") continue;
        for (let v = 1; v <= 9; v++) {
          const d = String(v);
          if (!ok(r, c, d)) continue;
          board[r][c] = d;
          if (solve()) return true;
          board[r][c] = ".";
        }
        return false; // nothing fits here: back up
      }
    return true;
  };
  solve();
}

