            br, bc = r - r % 3, c - c % 3
            for k in range(9):
                if board[r][k] == d or board[k][c] == d:
                    return False
                if board[br + k // 3][bc + k % 3] == d:
                    return False
            return True

        def solve():
            for r in range(9):
                for c in range(9):
                    if board[r][c] != ".":
                        continue
                    for v in "123456789":
                        if ok(r, c, v):
                            board[r][c] = v
                            if solve():
                                return True
                            board[r][c] = "."
                    return False  # nothing fits here: back up
            return True

        solve()

