function solveSudoku(board: string[][]): void {
  const rows = new Array(9).fill(0), cols = new Array(9).fill(0), boxes = new Array(9).fill(0);
  const empty: number[] = [];
  const box = (r: number, c: number) => Math.floor(r / 3) * 3 + Math.floor(c / 3);
  for (let r = 0; r < 9; r++)
    for (let c = 0; c < 9; c++) {
      if (board[r][c] === ".") { empty.push(r * 9 + c); continue; }
      const bit = 1 << (+board[r][c] - 1);
      rows[r] |= bit; cols[c] |= bit; boxes[box(r, c)] |= bit;
    }
  const bits = (x: number) => { let n = 0; while (x) { x &= x - 1; n++; } return n; };

  const solve = (left: number): boolean => {
    if (left === 0) return true;
    // pick the empty cell with the fewest free digits and swap it to position left - 1
    let best = -1, bestFree = 0, bestCount = 10;
    for (let i = 0; i < left; i++) {
      const r = Math.floor(empty[i] / 9), c = empty[i] % 9;
      const free = ~(rows[r] | cols[c] | boxes[box(r, c)]) & 0x1ff;
      const n = bits(free);
      if (n < bestCount) { best = i; bestFree = free; bestCount = n; if (n <= 1) break; }
    }
    if (bestCount === 0) return false;
    [empty[best], empty[left - 1]] = [empty[left - 1], empty[best]];
    const cell = empty[left - 1], r = Math.floor(cell / 9), c = cell % 9, b = box(r, c);
    for (let free = bestFree; free; free &= free - 1) {
      const bit = free & -free;
      rows[r] |= bit; cols[c] |= bit; boxes[b] |= bit;
      board[r][c] = String(31 - Math.clz32(bit) + 1);
      if (solve(left - 1)) return true;
      rows[r] ^= bit; cols[c] ^= bit; boxes[b] ^= bit;
    }
    board[r][c] = ".";
    return false;
  };
  solve(empty.length);
}

